        writeNumeric("n-1", "num-a", "rec-1", 5).andExpect(status().isOk());
        writeNumeric("n-1", "num-a", "rec-1", 6)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("REQUEST_ID_CONFLICT"));
